//go:build ignore

// Development compiler of source-owned indexed scenes and static drawing layers.
package eightsword
import("bytes";"encoding/binary";"encoding/json";"fmt";"hash/fnv";"image";"image/png";"os";"path/filepath";"sort";"strings";"testing")
var rustIntroObserve func(*sourceIntroAdapter,*ownedIntroScene,string)
func introHash(b []byte)uint64{h:=fnv.New64a();h.Write(b);return h.Sum64()}
type introTexture struct{w,h int;kind byte;raw []byte}
type introNode struct{ms uint32;stage string;mode,cue byte;native,clean,palette uint32;revealed uint32;ops []uint32}
type introSample struct{frame int;s *ownedIntroScene;adapter *sourceIntroAdapter}
type introExport struct{t *testing.T; e *Engine;dir string;begin uint64;begun bool;textures []introTexture;blobs [][]byte;ops [][]byte;frames []introNode;texIDs,blobIDs,opIDs map[string]uint32;imageIDs map[image.Image]uint32;alphaIDs map[string]uint32;order []uint16;prelude uint32;samples map[string]introSample}
func(p *introExport)blob(b []byte)uint32{k:=fmt.Sprintf("%d/%x",len(b),introHash(b));if id,ok:=p.blobIDs[k];ok{return id};id:=uint32(len(p.blobs));p.blobIDs[k]=id;p.blobs=append(p.blobs,append([]byte(nil),b...));return id}
func(p *introExport)texture(im image.Image,kind byte)uint32{if id,ok:=p.imageIDs[im];ok{return id};b:=im.Bounds();var raw []byte
 for y:=0;y<b.Dy();y++{for x:=0;x<b.Dx();x++{if kind==0{r,g,bb,a:=im.At(b.Min.X+x,b.Min.Y+y).RGBA();for _,v:=range []uint32{r,g,bb,a}{raw=binary.LittleEndian.AppendUint16(raw,uint16(v))}}else{v:=im.(*image.NRGBA).NRGBAAt(x+b.Min.X,y+b.Min.Y);raw=append(raw,v.R,v.G,v.B,v.A)}}}
 k:=fmt.Sprintf("%d/%d/%d/%x",b.Dx(),b.Dy(),kind,introHash(raw));if id,ok:=p.texIDs[k];ok{return id};id:=uint32(len(p.textures));p.texIDs[k]=id;p.textures=append(p.textures,introTexture{b.Dx(),b.Dy(),kind,raw});p.imageIDs[im]=id;return id}
func(p *introExport)op(v ...any)uint32{var b bytes.Buffer;for _,x:=range v{if e:=binary.Write(&b,binary.LittleEndian,x);e!=nil{p.t.Fatal(e)}};k:=string(b.Bytes());if id,ok:=p.opIDs[k];ok{return id};id:=uint32(len(p.ops));p.opIDs[k]=id;p.ops=append(p.ops,append([]byte(nil),b.Bytes()...));return id}
func(p *introExport)blit(im image.Image,x,y int,source bool)uint32{k:=byte(0);if source{k=1};return p.op(k,p.texture(im,0),uint16(x),uint16(y))}
func(p *introExport)rows(rows []uint32,page uint32)[]uint16{v:=make([]uint16,len(rows));for i,n:=range rows{if n<page||n-page>=16000{p.t.Fatal("row")};v[i]=uint16(n-page)};return v}
func(p *introExport)capture(a *sourceIntroAdapter,s *ownedIntroScene,stage string){
 if !p.begun{p.begin=p.e.Oracle.Cycles();p.begun=true};if len(p.frames)>0&&p.frames[len(p.frames)-1].ms==uint32((p.e.Oracle.Cycles()-p.begin)/3000){return}
 n:=128000;if s.Mode==0x13{n=64000};raw:=s.Native[s.Start:s.Start+n];clean:=append([]byte(nil),raw...);ids:=map[uint32]bool{}
 if s.Mode==0xe{for i,id:=range s.Owners[s.Start:s.Start+n]{if id!=0{g:=s.Glyphs[id];if g.Rune==0{p.t.Fatal("unmapped glyph")};clean[i]=s.Backing[s.Start+i];ids[id]=true}}}
 f:=introNode{ms:uint32((p.e.Oracle.Cycles()-p.begin)/3000),stage:stage,mode:s.Mode,native:p.blob(raw),clean:p.blob(clean)};var pal []byte;for _,c:=range s.Palette{pal=append(pal,c[:]...)};f.palette=p.blob(pal);/* V1 cue is reserved; V2 compiler uses source Start/Stop events. */
 art:=a.art();page:=s.Pages[s.Start]
 if s.Prelude{for _,v:=range s.Reveal{if v{f.revealed++}};if len(p.order)==0{for _,at:=range a.order{p.order=append(p.order,uint16(at))};p.prelude=p.texture(art.Prelude,0)}}else{
  switch page.Kind{
  case "publisher":for _,im:=range []image.Image{art.PublisherErase,art.IconErase}{if im!=nil{f.ops=append(f.ops,p.op(byte(2),p.texture(im,0)))}};if art.IconArt!=nil{f.ops=append(f.ops,p.blit(art.IconArt,0,0,false))};var ts [3]uint32;for i,name:=range []string{"noto","lishu","caoshu"}{if e:=p.e.SetFont(name);e!=nil{p.t.Fatal(e)};ts[i]=p.texture(a.art().PublisherInk,0)};p.e.SetFont("noto");f.ops=append(f.ops,p.op(byte(7),ts,uint16(0),uint16(0)))
  case "title":var ts [3]uint32;for i,name:=range []string{"noto","lishu","caoshu"}{p.e.SetFont(name);ts[i]=p.texture(a.art().Title,0)};p.e.SetFont("noto");f.ops=append(f.ops,p.op(byte(8),ts,uint16(48),uint16(300)))
  case "story":f.ops=append(f.ops,p.blit(art.Story,0,0,true))
  case "museum":m:=page.Museum;if m!=nil{bg:=image.Image(art.MuseumArt);if m.role=="right"{bg=art.MuseumScenes["right:a-purple"]};f.ops=append(f.ops,p.blit(bg,0,300,true));if m.scene!=nil&&m.scene.portrait!=nil{f.ops=append(f.ops,p.blit(art.MuseumScenes["portrait:all"],336,120,true))};if m.actor!=nil{rows:=p.rows(m.actor.rows,m.actor.page);f.ops=append(f.ops,p.op(byte(4),p.texture(m.actor.sprite,1),byte(len(rows)),rows));if m.scene!=nil&&m.scene.beam!=nil{b:=m.scene.beam;r,n:=b.record,b.record.w*b.record.h;var tint [3]byte;for i:=0;i<n;i++{for bit:=0;bit<8;bit++{if r.raw[4+5*n+i]&(128>>bit)==0{continue};index:=byte(0);for plane:=0;plane<4;plane++{index|=((r.raw[4+plane*n+i]>>uint(7-bit))&1)<<uint(plane)};c:=s.Palette[index];if int(c[0])+int(c[1])+int(c[2])>int(tint[0])+int(tint[1])+int(tint[2]){tint=c}}};rows=p.rows(b.rows,b.page);f.ops=append(f.ops,p.op(byte(5),p.texture(art.MuseumScenes["beam:all"],1),byte(len(rows)),rows,tint))}}else{bounds:=image.Rectangle{};for y:=50;y<150;y++{for x:=0;x<640;x++{if m.ink.RGBAAt(x,y).A!=0{bounds=bounds.Union(image.Rect(x,y,x+1,y+1))}}};if bounds.Empty(){bounds=image.Rect(0,0,1,1)};f.ops=append(f.ops,p.op(byte(6),p.texture(m.ink.SubImage(bounds),0),uint16(bounds.Min.X),uint16(bounds.Min.Y)))}}
  }
  ordered:=[]int{};for id:=range ids{ordered=append(ordered,int(id))};sort.Ints(ordered)
  for _,id:=range ordered{g:=s.Glyphs[uint32(id)];if g.Rune==' '{continue};mask:=make([]byte,g.Width*15);for y:=0;y<15;y++{for x:=0;x<g.Width;x++{if s.Owners[s.Start+(g.Y+y)*640+g.X+x]==uint32(id){mask[y*g.Width+x]=1}}};var ts [3]uint32
   for i,name:=range []string{"noto","lishu","caoshu"}{key:=fmt.Sprintf("%s/%d/%d",name,g.Rune,g.Width);if id,ok:=p.alphaIDs[key];ok{ts[i]=id;continue};p.e.SetFont(name);font:=a.art().Font;ink,ok:=font.Glyphs[g.Rune];if !ok{p.t.Fatal("glyph",g.Rune)};alpha:=image.NewRGBA(image.Rect(0,0,g.Width*3,90));iw,ih:=ink.Ink[2],ink.Ink[3];dw,dh:=min(iw,g.Width*3),min(ih,90);left,top:=(g.Width*3-dw)/2,(90-dh)/2;for y:=0;y<dh;y++{for x:=0;x<dw;x++{_,_,_,v:=font.Atlas.At(ink.Ink[0]+x*iw/dw,ink.Ink[1]+y*ih/dh).RGBA();alpha.Pix[((top+y)*g.Width*3+left+x)*4+3]=byte(v>>8)}};ts[i]=p.texture(alpha,0);p.alphaIDs[key]=ts[i]};p.e.SetFont("noto");color:=s.Palette[g.FG];if page.Kind=="story"{color=[3]byte{245,207,113}};f.ops=append(f.ops,p.op(byte(3),ts,uint16(g.X*3),uint16(g.Y*6),color,p.blob(mask)))
  }
 }
 if len(p.frames)>0{last:=p.frames[len(p.frames)-1];tmp:=f;tmp.ms=last.ms;if fmt.Sprint(tmp)==fmt.Sprint(last){return}}
 p.frames=append(p.frames,f)
 if stage!=""&&stage!="prelude-handoff"{keep:=stage!="prelude-reveal"||f.revealed>=32000&&f.revealed<34000;if keep{p.samples[stage]=introSample{len(p.frames)-1,cloneOwnedIntroScene(s),a}}}
}
func(p *introExport)finish(){duration:=uint32((p.e.Oracle.Cycles()-p.begin)/3000);if len(p.order)!=64000||len(p.frames)<30{p.t.Fatal("incomplete intro")};var out bytes.Buffer;put:=func(v any){if e:=binary.Write(&out,binary.LittleEndian,v);e!=nil{p.t.Fatal(e)}};out.WriteString("8SINTRO1");put(duration);put(p.prelude);put(uint32(len(p.order)));put(p.order)
 put(uint32(len(p.textures)));for _,v:=range p.textures{put(uint16(v.w));put(uint16(v.h));put(v.kind);out.Write(v.raw)}
 put(uint32(len(p.blobs)));for _,v:=range p.blobs{put(uint32(len(v)));var runs bytes.Buffer;for i:=0;i<len(v);{j:=i+1;for j<len(v)&&j-i<65535&&v[j]==v[i]{j++};binary.Write(&runs,binary.LittleEndian,uint16(j-i));runs.WriteByte(v[i]);i=j};put(uint32(runs.Len()));out.Write(runs.Bytes())}
 put(uint32(len(p.ops)));for _,v:=range p.ops{put(uint16(len(v)));out.Write(v)};put(uint32(len(p.frames)));for _,v:=range p.frames{put(v.ms);put(byte(len(v.stage)));out.WriteString(v.stage);put(v.mode);put(v.cue);put(v.native);put(v.clean);put(v.palette);put(v.revealed);put(uint16(len(v.ops)));put(v.ops)}
 sum:=introHash(out.Bytes());put(sum);os.WriteFile(filepath.Join(p.dir,"intro.bin"),out.Bytes(),0644);os.WriteFile(filepath.Join(p.dir,"intro-plan.tsv"),[]byte(fmt.Sprintf("%d\t%016x\t%d\n",duration,sum,len(p.frames))),0644)
 var refs bytes.Buffer;refs.WriteString("# frame ms stage original noto lishu caoshu\n");names:=[]string{};for n:=range p.samples{names=append(names,n)};sort.Strings(names)
 for _,stage:=range names{v:=p.samples[stage];fmt.Fprintf(&refs,"%d\t%d\t%s",v.frame,p.frames[v.frame].ms,stage);for _,name:=range []string{"original","noto","lishu","caoshu"}{p.e.SetFont("noto");hd:=name!="original";if hd{p.e.SetFont(name)};im:=renderOwnedIntro(v.s,v.adapter.art(),hd);fmt.Fprintf(&refs,"\t%016x",introHash(im.Pix));file,_:=os.Create(filepath.Join(p.dir,stage+"-"+name+".png"));png.Encode(file,im);file.Close()};fmt.Fprintln(&refs)};os.WriteFile(filepath.Join(p.dir,"intro-reference.tsv"),refs.Bytes(),0644)
 meta:=map[string]any{"duration_ms":duration,"begin_cycle":p.begin,"end_cycle":p.e.Oracle.Cycles(),"frames":len(p.frames),"textures":len(p.textures),"indexed_canvases_and_masks":len(p.blobs),"ops":len(p.ops),"samples":len(names),"packet_bytes":out.Len(),"plan_fnv":fmt.Sprintf("%016x",sum),"music_events":p.e.Music.Events,"source":"Normal PREDELLA boot; source-owned adapter state and immutable approved textures. No guest RAM or IP injection; no RGB movie or VM in runtime.","prelude_order":len(p.order),"timing":"3000cycle/ms;10ms stable nodes, presentation approximation"};b,_:=json.MarshalIndent(meta,"","  ");os.WriteFile(filepath.Join(p.dir,"receipt.json"),append(b,'\n'),0644);p.t.Logf("intro %s",b)
}
func TestRustIntroExport(t *testing.T){out:=os.Getenv("INTRO_OUT");if out==""{t.Skip("explicit export output required")};e,err:=Open(Options{Root:os.Getenv("INTRO_GAME"),Assets:os.Getenv("INTRO_ART"),Saves:filepath.Join(out,"scratch"),HD:true});if err!=nil{t.Fatal(err)};defer e.Close();e.Oracle.SetClock(12,0,0,0);e.EnableLiveClock(3000);p:=&introExport{t:t,e:e,dir:out,texIDs:map[string]uint32{},blobIDs:map[string]uint32{},opIDs:map[string]uint32{},samples:map[string]introSample{},imageIDs:map[image.Image]uint32{},alphaIDs:map[string]uint32{}};rustIntroObserve=p.capture;defer func(){rustIntroObserve=nil}();advance:=func(n int){for ;n>0;n-=10{if err:=e.AdvanceCycles(30000);err!=nil{t.Fatal(err)};e.Frame();if e.Exited{t.Fatal("early exit")}}};advance(200);for i:=0;i<2;i++{if err:=e.Oracle.TypeKeys("1");err!=nil{t.Fatal(err)};advance(250)};for i:=0;i<9000&&!e.PAMLoaded;i++{advance(10)};if !e.PAMLoaded{t.Fatal("no PAM")};p.finish();e.Oracle.SaveStateFile(filepath.Join(out,"original-handoff.state"));for _,s:=range []string{"publisher","title","museum-left","museum-right","museum-portrait","museum-beam","prelude-complete","story-1-text","story-2-text","story-3-text","story-4-text","story-5-text"}{if _,ok:=p.samples[s];!ok{t.Fatal("missing",s)}};_ = strings.TrimSpace("")}
